package Google::Cloud::Certificatemanager::V1::CertificateManager::CertificateManagerClient;

=pod

=head2 Service Client: Google::Cloud::Certificatemanager::V1::CertificateManager::CertificateManagerClient

Client stub representing the remote C<CertificateManager> gRPC service. Delegates call dispatching to L<Google::gRPC::Client>.

=head3 target

The endpoint target address. Defaults to C<certificatemanager.googleapis.com:443>.

=head3 credentials

The authentication credentials provider. Defaults to application default credentials via L<Google::Auth>.

=cut

use Moo;
use Google::Auth;
