=head2 Google::Cloud::Certificatemanager::V1::CertificateManager::Certificate

Defines TLS certificate.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Identifier. A user-defined name of the certificate. Certificate names must
be unique globally and match pattern
`projects/*/locations/*/certificates/*`.

=item * C<< $msg->description() >> / C<< $msg->description($value) >>

Type: C<String>

Optional. One or more paragraphs of text description of a certificate.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The creation timestamp of a Certificate.

=item * C<< $msg->update_time() >> / C<< $msg->update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The last update timestamp of a Certificate.

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Cloud::Certificatemanager::V1::CertificateManager::Certificate::LabelsEntry>)

Optional. Set of labels associated with a Certificate.

=item * C<< $msg->self_managed() >> / C<< $msg->self_managed($value) >>

Type: C<Message> (L<Google::Cloud::Certificatemanager::V1::CertificateManager::Certificate::SelfManagedCertificate>)

If set, defines data of a self-managed certificate.

=item * C<< $msg->managed() >> / C<< $msg->managed($value) >>

Type: C<Message> (L<Google::Cloud::Certificatemanager::V1::CertificateManager::Certificate::ManagedCertificate>)

If set, contains configuration and state of a managed certificate.

=item * C<< $msg->managed_identity() >> / C<< $msg->managed_identity($value) >>

Type: C<Message> (L<Google::Cloud::Certificatemanager::V1::CertificateManager::Certificate::ManagedIdentityCertificate>)

If set, contains configuration and state of a managed identity
certificate.

=item * C<< $msg->san_dnsnames() >> / C<< $msg->san_dnsnames($value) >>

Type: C<String>

Output only. The list of Subject Alternative Names of dnsName type defined
in the certificate (see RFC 5280 4.2.1.6). Managed certificates that
haven't been provisioned yet have this field populated with a value of the
managed.domains field.

=item * C<< $msg->pem_certificate() >> / C<< $msg->pem_certificate($value) >>

Type: C<String>

Output only. The PEM-encoded certificate chain.

=item * C<< $msg->expire_time() >> / C<< $msg->expire_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The expiry timestamp of a Certificate.

=item * C<< $msg->scope() >> / C<< $msg->scope($value) >>

Type: C<Enum> (L<Google::Cloud::Certificatemanager::V1::Certificate::Scope>)

Optional. Immutable. The scope of the certificate.

=item * C<< $msg->used_by() >> / C<< $msg->used_by($value) >>

Type: C<Message> (L<Google::Cloud::Certificatemanager::V1::CertificateManager::Certificate::UsedBy>)

Output only. The list of resources that use this Certificate.

=item * C<< $msg->tags() >> / C<< $msg->tags($value) >>

Type: C<Message> (L<Google::Cloud::Certificatemanager::V1::CertificateManager::Certificate::TagsEntry>)

Optional. Input only. Immutable. Tag keys/values directly bound to this
resource. For example:
  "123/environment": "production",
  "123/costCenter": "marketing"

