=head2 Google::Cloud::Certificatemanager::V1::CertificateManager::DnsAuthorization

A DnsAuthorization resource describes a way to perform domain authorization
for certificate issuance.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Identifier. A user-defined name of the dns authorization. DnsAuthorization
names must be unique globally and match pattern
`projects/*/locations/*/dnsAuthorizations/*`.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The creation timestamp of a DnsAuthorization.

=item * C<< $msg->update_time() >> / C<< $msg->update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The last update timestamp of a DnsAuthorization.

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Cloud::Certificatemanager::V1::CertificateManager::DnsAuthorization::LabelsEntry>)

Optional. Set of labels associated with a DnsAuthorization.

=item * C<< $msg->description() >> / C<< $msg->description($value) >>

Type: C<String>

Optional. One or more paragraphs of text description of a DnsAuthorization.

=item * C<< $msg->domain() >> / C<< $msg->domain($value) >>

Type: C<String>

Required. Immutable. A domain that is being authorized. A DnsAuthorization
resource covers a single domain and its wildcard, e.g. authorization for
`example.com` can be used to issue certificates for `example.com` and
`*.example.com`.

=item * C<< $msg->dns_resource_record() >> / C<< $msg->dns_resource_record($value) >>

Type: C<Message> (L<Google::Cloud::Certificatemanager::V1::CertificateManager::DnsAuthorization::DnsResourceRecord>)

Output only. DNS Resource Record that needs to be added to DNS
configuration.

=item * C<< $msg->type() >> / C<< $msg->type($value) >>

Type: C<Enum> (L<Google::Cloud::Certificatemanager::V1::DnsAuthorization::Type>)

Optional. Immutable. Type of DnsAuthorization. If unset during resource
creation the following default will be used:
- in location `global`: FIXED_RECORD,
- in other locations: PER_PROJECT_RECORD.

=item * C<< $msg->tags() >> / C<< $msg->tags($value) >>

Type: C<Message> (L<Google::Cloud::Certificatemanager::V1::CertificateManager::DnsAuthorization::TagsEntry>)

Optional. Input only. Immutable. Tag keys/values directly bound to this
resource. For example:
  "123/environment": "production",
  "123/costCenter": "marketing"

=back

=head3 Enum: DnsAuthorization::Type

=over 4

=item * C<TYPE_UNSPECIFIED> => C<0>

=item * C<FIXED_RECORD> => C<1>

=item * C<PER_PROJECT_RECORD> => C<2>

=back

